let intent =$input.first().json.content.parts[0].text;

// remove quotes + spaces
intent = intent.replace(/"/g, '').trim().toLowerCase();

// safety fallback
const allowed = ["medical", "greeting", "spam", "irrelevant"];
if (!allowed.includes(intent)) {
  intent = "irrelevant";
}

return [
  {
    json: {
      intent
    }
  }
];

